from django.db import models

class BlogPost(models.Model):
    title = models.CharField(max_length=100)
    slug = models.SlugField(unique=True)

    def save(self, *args, **kwargs):
        # Automatically generate slug from title if not provided
        if not self.slug:
            self.slug = slugify(self.title)
        super(BlogPost, self).save(*args, **kwargs)

from django.shortcuts import render, redirect
from .forms import UploadFileForm
from .models import UploadedFile

def upload_file(request):
    if request.method == 'POST':
        form = UploadFileForm(request.POST, request.FILES)
        if form.is_valid():
            form.save()
            return redirect('success')
    else:
        form = UploadFileForm()
    return render(request, 'uploadfile/upload.html', {'form': form})

def success(request):
    return render(request, 'uploadfile/success.html')

import pip

def get_django_version():
    try:
        # Try to get the version of Django installed via pip
        result = pip.main(['show', 'django'])
        lines = result.stdout.decode('utf-8').split('\n')
        for line in lines:
            if line.startswith('Version'):
                return line.split(': ')[1]
        return None
    except Exception as e:
        print(f"Error getting Django version: {e}")
        return None

# Check Django version
version = get_django_version()
if version:
    print(f"Django version installed: {version}")
else:
    print("Failed to retrieve Django version.")

