import http.cookies
from typing import Dict, Any
from datetime import datetime
import logging

# Example session management code
class SessionManager:
    def __init__(self):
        self.sessions = {}

    def create_session(self) -> str:
        # Create a new session ID
        session_id = f"session_{datetime.now().strftime('%Y%m%d%H%M%S')}"
        self.sessions[session_id] = {}
        return session_id

    def get_session(self, session_id: str) -> Dict[str, Any]:
        # Retrieve session data
        return self.sessions.get(session_id, {})

    def set_session_variable(self, session_id: str, key: str, value: Any):
        # Set a session variable
        if session_id not in self.sessions:
            raise ValueError("Session does not exist")
        self.sessions[session_id][key] = value

    def get_session_variable(self, session_id: str, key: str) -> Any:
        # Get a session variable
        if session_id not in self.sessions:
            raise ValueError("Session does not exist")
        return self.sessions[session_id].get(key)

# Example instance instantiation code
class MyServlet:
    def __init__(self, session_manager: SessionManager):
        self.session_manager = session_manager

    def process_request(self, request: Dict[str, Any]):
        # Process a request and use session variables
        session_id = request.get('session_id')
        user_name = request.get('username')

        if 'username' not in request:
            raise ValueError("Username required")

        session_data = self.session_manager.get_session(session_id)
        if 'last_access' not in session_data:
            session_data['last_access'] = datetime.now()

        session_data['user_name'] = user_name
        self.session_manager.set_session_variable(session_id, 'user_name', user_name)

        # Example operation
        print(f"User {user_name} accessed at {session_data['last_access']}")

# Example usage
if __name__ == "__main__":
    session_manager = SessionManager()
    my_servlet = MyServlet(session_manager)

    # Simulate multiple users accessing the servlet
    for i in range(3):
        session_id = session_manager.create_session()
        request = {
            'session_id': session_id,
            'username': f"user_{i+1}"
        }
        my_servlet.process_request(request)

