import sys

# Function to check if PHP is thread-safe
def is_php_thread_safe():
    # Check for the presence of --enable-maintainer-zts in the configure command line arguments
    configure_args = sys.argv
    if '--enable-maintainer-zts' in configure_args:
        return True
    else:
        return False

# Example usage
