Title: How to loop through a plain JavaScript object with the objects as members.
Body: <p>How can I loop through all members in a JavaScript object, including values that are objects?</p>
<p>For example, how could I loop through this (accessing the &quot;your_name&quot; and &quot;your_message&quot; for each)?</p>
<pre><code>var validation_messages = {
    &quot;key_1&quot;: {
        &quot;your_name&quot;: &quot;jimmy&quot;,
        &quot;your_msg&quot;: &quot;hello world&quot;
    },
    &quot;key_2&quot;: {
        &quot;your_name&quot;: &quot;billy&quot;,
        &quot;your_msg&quot;: &quot;foo equals bar&quot;
    }
}
</code></pre>

answer:
# Define the JavaScript object
validation_messages = {
    "key_1": {
        "your_name": "jimmy",
        "your_msg": "hello world"
    },
    "key_2": {
        "your_name": "billy",
        "your_msg": "foo equals bar"
    }
}

# Using for...in loop
for key in validation_messages:
    if validation_messages.has_key(key):
        obj = validation_messages[key]
        print(f'Key: {key}')
        print(f'Your Name: {obj["your_name"]}')
        print(f'Your Message: {obj["your_msg"]}')
        print('-')

# Using Object.keys() and forEach()
Object.keys(validation_messages).forEach(function(key) {
    var obj = validation_messages[key];
    console.log(`Key: ${key}`);
    console.log(`Your Name: ${obj.your_name}`);
    console.log(`Your Message: ${obj.your_msg}`);
    console.log('-');
});

