# Import necessary libraries
from flask import Flask, request, jsonify
import jwt
import os

app = Flask(__name__)

# Set up environment variables for secret key
SECRET_KEY = os.getenv('SECRET_KEY', 'default_secret_key')

@app.route('/login', methods=['POST'])
def login():
    # Assume user credentials are validated here
    username = request.json.get('username')
    password = request.json.get('password')

    if username == 'admin' and password == 'password':
        # Create a JWT token
        payload = {
            'user': username,
            'exp': datetime.utcnow() + timedelta(minutes=30)
        }
        token = jwt.encode(payload, SECRET_KEY, algorithm='HS256')

        return jsonify({'token': token}), 200
    else:
        return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/protected', methods=['GET'])
def protected():
    # Verify the JWT token
    auth_header = request.headers.get('Authorization')
    if auth_header:
        try:
            token = auth_header.split(' ')[1]
            decoded_token = jwt.decode(token, SECRET_KEY, algorithms=['HS256'])
            return jsonify({'message': 'Protected resource accessed by {}'.format(decoded_token['user'])}), 200
        except jwt.ExpiredSignatureError:
            return jsonify({'error': 'Token has expired'}), 401
        except jwt.InvalidTokenError:
            return jsonify({'error': 'Invalid token'}), 401
    else:
        return jsonify({'error': 'No token provided'}), 401

if __name__ == '__main__':
    app.run(debug=True)
```

This solution provides a basic implementation of a RESTful API with JWT authentication. It includes routes for user login and accessing a protected resource. The JWT tokens are generated upon successful login and verified in each subsequent request. The use of environment variables for the secret key enhances security by keeping sensitive information out of source code.

