# Function to find the location of libpython
def find_libpython():
    # Check the environment variable PYTHONPATH
    python_path = os.getenv('PYTHONPATH')
    if python_path:
        return python_path.split(':')

    # Check the default Python installation
    python_executable = sys.executable
    if python_executable:
        return [os.path.dirname(python_executable)]

    return None

