import os

def is_file_in_use(file_path):
    try:
        # Check if the file exists
        if not os.path.exists(file_path):
            return False

        # Open the file in read-only mode
        with open(file_path, 'rb') as f:
            # Read the first few bytes to check if the file is open
            f.read(1)
            return True

    except FileNotFoundError:
        # If the file does not exist, it cannot be opened
        return False
    except PermissionError:
        # If permission is denied, the file might be in use by another process
        return True

# Example usage
file_path = 'example.txt'
if is_file_in_use(file_path):
    print(f"The file '{file_path}' is in use.")
else:
    print(f"The file '{file_path}' is not in use.")

