# Define the function to sort a dictionary by its keys
def sort_dict_by_key(input_dict):
    # Return the sorted dictionary using the sorted function with the key parameter set to the keys of the input dictionary
    return dict(sorted(input_dict.items(), key=lambda x: x[0]))

