import os

# Function to authenticate with GitHub
def authenticate_with_github():
    # Check if credentials are available
    if os.getenv('GIT_USERNAME') and os.getenv('GIT_PASSWORD'):
        return True
    else:
        print("Please set your GIT_USERNAME and GIT_PASSWORD environment variables.")
        return False

# Main function to handle Git push authentication
def handle_git_push_authentication():
    if authenticate_with_github():
        print("Authentication successful.")
    else:
        print("Failed to authenticate. Please check your credentials.")

# Example usage
handle_git_push_authentication()

