# Define a class to represent a RESTful authentication system
class RESTfulAuthentication:
    def __init__(self, secret_key):
        self.secret_key = secret_key

    def authenticate(self, session_key):
        # Check if the session key matches the secret key
        if session_key == self.secret_key:
            return True
        else:
            return False

# Example usage of the RESTfulAuthentication class
if __name__ == "__main__":
    auth_system = RESTfulAuthentication("my_secret_key")

    # Test cases
    print(auth_system.authenticate("my_session_key"))  # Expected output: True
    print(auth_system.authenticate("wrong_session_key"))   # Expected output: False
```

In this solution, we have created a `RESTfulAuthentication` class with an initializer that takes a secret key as input. The `authenticate` method checks if the provided session key matches the secret key, returning `True` if they match and `False` otherwise. This simple implementation assumes that the session key is stored securely and not exposed in URLs or other sensitive data.

from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(128), nullable=False)

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    hashed_password = generate_password_hash(data['password'], method='sha256')
    new_user = User(username=data['username'], password_hash=hashed_password)
    db.session.add(new_user)
    db.session.commit()
    return jsonify({'message': 'User registered successfully'})

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    user = User.query.filter_by(username=data['username']).first()
    if user and check_password_hash(user.password_hash, data['password']):
        return jsonify({'message': 'Login successful'})
    else:
        return jsonify({'message': 'Invalid credentials'}), 401

if __name__ == '__main__':
    app.run(debug=True)

